#ifndef __SOIL_SENSOR_H
#define __SOIL_SENSOR_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stddef.h>
#include <stdbool.h>

/* 使用 ai_chat.h 中的 soil_data_s 定义 */

