static int init_ota_partitions(void)
{
  struct mtd_dev_s *mtd;
  int ret = OK;
  int i;

  for (i = 0; i < sizeof(g_ota_partition_table) / sizeof(g_ota_partition_table[0]); i++)
    {
      const struct ota_partition_s *part = &g_ota_partition_table[i];
      mtd = esp32s3_spiflash_alloc_mtdpart(part->offset, part->size, false);
      if (mtd == NULL)
        {
          syslog(LOG_ERR, "ERROR: Failed to alloc MTD for %s\n",
                 part->devpath);
          return -ENOMEM;
        }

      ret = register_mtddriver(part->devpath, mtd, 0755, NULL);
      if (ret < 0)
        {
          syslog(LOG_ERR, "ERROR: register_mtddriver %s failed: %d\n",
                 part->devpath, ret);
          return ret;
        }

      syslog(LOG_INFO, "OTA partition %s: offset=0x%06x size=0x%06x\n",
             part->devpath, part->offset, part->size);
    }

  /* Register the otadata partition (0xD000, 8KB) so the OTA app can
   * switch the active boot slot (standard ESP-IDF A/B boot metadata,
   * read by the second-stage bootloader).  Offset/size must match
   * partition_table.csv.
   */

  mtd = esp32s3_spiflash_alloc_mtdpart(0xD000, 0x2000, false);
  if (mtd == NULL)
    {
      syslog(LOG_ERR, "ERROR: Failed to alloc MTD for /dev/otadata\n");
      return -ENOMEM;
    }

  ret = register_mtddriver("/dev/otadata", mtd, 0755, NULL);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: register_mtddriver /dev/otadata failed: %d\n",
             ret);
      return ret;
    }

  syslog(LOG_INFO, "OTA partition /dev/otadata: offset=0x00d000 size=0x002000\n");

  return OK;
}
